def _canonical_json_sha256(value: Mapping[str, Any]) -> str:
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


RULESET_SHA256 = _canonical_json_sha256(RULESET_SPEC)


class DeltaChatRouteHandoffStateEvaluator(BaseEvaluator):
    """Evaluate human and automatic runs with one identical durable ruleset."""

    RULESET_SHA256 = RULESET_SHA256

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        udid = str(
            params.get("udid")
            or getattr(getattr(controller, "runtime", None), "udid", "")
            or ""
        ).strip()
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation.params.udid is required; no simulator fallback is allowed",
                metadata={
                    "task_id": TASK_ID,
                    "read_only": True,
                    "ruleset_sha256": RULESET_SHA256,
                },
            )

        expected_ruleset = str(params.get("expected_ruleset_sha256") or "").strip()
        observed_parameters = {
            "minimum_message_id": int(params.get("minimum_message_id", DEFAULT_MINIMUM_MESSAGE_ID)),
            "baseline_max_timestamp": int(params.get("baseline_max_timestamp", DEFAULT_BASELINE_MAX_TIMESTAMP)),
            "sent_state": int(params.get("sent_state", DEFAULT_SENT_STATE)),
        }
        expected_parameters = {
            "minimum_message_id": DEFAULT_MINIMUM_MESSAGE_ID,
            "baseline_max_timestamp": DEFAULT_BASELINE_MAX_TIMESTAMP,
            "sent_state": DEFAULT_SENT_STATE,
        }
        binding_checks = [
            self._check(
                "ruleset_binding",
                expected_ruleset == RULESET_SHA256,
                steps=[],
                dimension="binding",
                expected=RULESET_SHA256,
                observed=expected_ruleset or None,
                failure_reason="task YAML is not bound to this evaluator ruleset digest",
            ),
            self._check(
                "business_parameter_binding",
                observed_parameters == expected_parameters,
                steps=[],
                dimension="binding",
                expected=expected_parameters,
                observed=observed_parameters,
                failure_reason="task baseline or sent-state parameters differ from the ruleset",
            ),
        ]
        if not all(check["pass"] for check in binding_checks):
            return self._result(
                status=EvalStatus.FAIL,
                message="Handoff Log evaluator binding is invalid",
                udid=udid,
                checks=binding_checks,
                observed={},
            )

        try:
            group_root = _find_shared_app_group_root(
                udid=udid,
                group_id=DELTACHAT_APP_GROUP_ID,
            )
            db_paths = sorted((group_root / "accounts").glob("*/dc.db"))
            if len(db_paths) != 1:
                raise RuntimeError(
                    f"expected exactly one bound Delta Chat account database, found {len(db_paths)}"
                )
            documents = self._resolve_fsnotes_documents(
                udid=udid,
                bundle_id=str(params.get("fsnotes_bundle_id") or FSNOTES_BUNDLE_ID),
            )
            checks, observed = self._evaluate_bound_state(
                db_path=db_paths[0],
                documents=documents,
                minimum_message_id=observed_parameters["minimum_message_id"],
                baseline_max_timestamp=observed_parameters["baseline_max_timestamp"],
                sent_state=observed_parameters["sent_state"],
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read bound iOS app state: {type(exc).__name__}: {exc}",
                metadata={
                    "task_id": TASK_ID,
                    "udid": udid,
                    "read_only": True,
                    "ruleset_sha256": RULESET_SHA256,
                    "exception_type": type(exc).__name__,
                },
            )

        checks[0:0] = binding_checks
        failures = [check for check in checks if not check["pass"]]
        return self._result(
            status=EvalStatus.FAIL if failures else EvalStatus.PASS,
            message=(
                "Handoff Log note revisions, source provenance, exact line breaks, and Saved Messages order all match"
                if not failures
                else "Handoff Log workflow is missing or mismatches required durable evidence"
            ),
            udid=udid,
            checks=checks,
            observed=observed,
        )

    @classmethod
    def _evaluate_bound_state(
        cls,
        *,
        db_path: Path,
        documents: Path,
        minimum_message_id: int,
        baseline_max_timestamp: int,
        sent_state: int,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        with cls._sqlite_snapshot(db_path) as snapshot:
            connection = sqlite3.connect(f"file:{snapshot.as_posix()}?mode=ro", uri=True)
            connection.row_factory = sqlite3.Row
            try:
                chats = connection.execute(
                    "SELECT id,type,name,param FROM chats ORDER BY id"
                ).fetchall()
                messages = connection.execute(
                    """
                    SELECT m.id,m.chat_id,m.from_id,m.to_id,m.type,m.state,
                           m.timestamp,m.timestamp_sent,COALESCE(m.txt,'') AS txt,
                           COALESCE(m.param,'') AS param,COALESCE(c.name,'') AS chat_name,
                           COALESCE(c.type,0) AS chat_type
                    FROM msgs m
                    LEFT JOIN chats c ON c.id=m.chat_id
                    WHERE m.hidden=0 AND COALESCE(m.deleted,0)=0
                    ORDER BY m.id
                    """
                ).fetchall()
            finally:
                connection.close()

        checks: list[dict[str, Any]] = []
        self_chats = [
            row
            for row in chats
            if int(row["type"] or 0) == 100
            and cls._param_value(row["param"], "K") == "1"
        ]
        self_chat_id = int(self_chats[0]["id"]) if len(self_chats) == 1 else None
        checks.append(
            cls._check(
                "bound_saved_messages_chat",
                self_chat_id is not None,
                steps=list(range(1, 76)),
                dimension="final_object",
                expected="exactly one Delta Chat self-chat (type=100, K=1)",
                observed=[
                    {"id": int(row["id"]), "name": str(row["name"])}
                    for row in self_chats
                ],
                failure_reason="Saved Messages self-chat is missing or ambiguous",
            )
        )

        baseline_rows = [row for row in messages if int(row["id"]) < minimum_message_id]
        new_saved_rows = [
            row
            for row in messages
            if self_chat_id is not None
            and int(row["chat_id"]) == self_chat_id
            and int(row["id"]) >= minimum_message_id
        ]
        checks.append(
            cls._check(
                "saved_messages_output_count",
                len(new_saved_rows) == 2,
                steps=[34, 75],
                dimension="final_object",
                expected={"count": 2, "minimum_message_id": minimum_message_id},
                observed={
                    "count": len(new_saved_rows),
                    "ids": [int(row["id"]) for row in new_saved_rows],
                },
                failure_reason="Saved Messages does not contain exactly the two task attachments",
            )
        )

        attachment_rows = [
            row
            for row in new_saved_rows
            if int(row["type"]) == 60
            and cls._param_value(row["param"], "v") in NOTE_NAMES
        ]
        attachment_rows.sort(key=lambda row: int(row["id"]))
        attachment_payloads = [
            cls._attachment_blob(
                db_path=db_path,
                row=row,
                sent_state=sent_state,
                baseline_max_timestamp=baseline_max_timestamp,
            )
            for row in attachment_rows
        ]
        v1_evidence, v1_bytes = attachment_payloads[0] if len(attachment_payloads) >= 1 else ({}, b"")
        v2_evidence, v2_bytes = attachment_payloads[1] if len(attachment_payloads) >= 2 else ({}, b"")
        # The FSNotes creation title is app-managed, not a typed content line;
        # strip only that explicit prefix before every content comparison and
        # keep every remaining byte/line exact.
        v1_content = cls._strip_app_title(v1_bytes)
        v2_content = cls._strip_app_title(v2_bytes)
        v2_lines = cls._logical_lines(v2_content)

        selected_sources: dict[str, dict[str, Any]] = {}
        for spec in SOURCE_SPECS:
            candidates = [
                row
                for row in baseline_rows
                if str(row["chat_name"]) == str(spec["chat"])
                and str(spec["token"]) in str(row["txt"])
                and str(row["txt"]) in v2_lines
            ]
            selected = candidates[0] if len(candidates) == 1 else None
            if selected is not None:
                selected_sources[str(spec["key"])] = cls._message_summary(selected)
            checks.append(
                cls._check(
                    f"source_provenance:{spec['key']}",
                    selected is not None,
                    steps=list(spec["steps"]),
                    dimension="source_process",
                    expected={
                        "chat": spec["chat"],
                        "token": spec["token"],
                        "complete_message_as_one_line": True,
                    },
                    observed=[cls._message_summary(row) for row in candidates],
                    failure_reason=(
                        "the final note does not contain exactly one complete matching baseline "
                        f"message from {spec['chat']}"
                    ),
                )
            )

        expected_v1_lines = cls._resolve_line_spec(V1_LINE_SPEC, selected_sources)
        expected_v2_lines = cls._resolve_line_spec(V2_LINE_SPEC, selected_sources)
        expected_v1_bytes = cls._expected_bytes(expected_v1_lines)
        expected_v2_bytes = cls._expected_bytes(expected_v2_lines)
        source_keys = [str(spec["key"]) for spec in SOURCE_SPECS]
        source_positions = [
            v2_lines.index(str(selected_sources[key]["text"]))
            for key in source_keys
            if key in selected_sources and str(selected_sources[key]["text"]) in v2_lines
        ]
        checks.append(
            cls._check(
                "source_messages_in_instruction_order",
                len(source_positions) == len(source_keys)
                and source_positions == sorted(source_positions),
                steps=[14, 27, 45, 58],
                dimension="source_process",
                expected=[str(spec["chat"]) for spec in SOURCE_SPECS],
                observed={"source_keys": source_keys, "line_positions": source_positions},
                failure_reason="the four complete source messages are not in Mei, Nora, Alice, Bob order",
            )
        )

        # Exactly one of the two documented on-disk renderings must exist; a
        # title-only file next to the title+heading file is ambiguous -> FAIL.
        note_candidates = [
            path for path in (documents / name for name in NOTE_NAMES) if path.is_file()
        ]
        note_path = note_candidates[0] if len(note_candidates) == 1 else None
        note_bytes = note_path.read_bytes() if note_path is not None else b""
        note_content = cls._strip_app_title(note_bytes)
        if note_path is not None:
            note_stat = note_path.stat()
            birthtime = float(getattr(note_stat, "st_birthtime", note_stat.st_mtime))
            mtime = float(note_stat.st_mtime)
        else:
            birthtime = 0.0
            mtime = 0.0
        checks.append(
            cls._check(
                "fsnotes_object_new",
                note_path is not None and max(birthtime, mtime) > baseline_max_timestamp,
                steps=[7, 8],
                dimension="final_object",
                expected={
                    "filename": NOTE_NAME,
                    "allowed_names": list(NOTE_NAMES),
                    "timestamp_after": baseline_max_timestamp,
                },
                observed={
                    "matches": [path.name for path in note_candidates],
                    "birthtime": birthtime or None,
                    "mtime": mtime or None,
                },
                failure_reason="the unique post-baseline Handoff Log FSNotes object is missing or ambiguous",
            )
        )

        v1_exact = (
            len(attachment_payloads) == 2
            and expected_v1_bytes is not None
            and v1_content == expected_v1_bytes
        )
        checks.append(
            cls._check(
                "shared_v1_exact_lines_and_newlines",
                v1_exact,
                steps=[7, 8, 9, 10, 11, 12, 14, 15, 16, 23, 24, 25, 27, 28, 29],
                dimension="content_parameter",
                expected={
                    "lines": expected_v1_lines,
                    "separator": "exactly one LF between adjacent lines and no trailing LF",
                    "newline_steps": [10, 12, 15, 23, 25, 28],
                },
                observed={
                    "lines": cls._logical_lines(v1_content),
                    "size": len(v1_bytes),
                    "content_size": len(v1_content),
                    "app_title_prefix_stripped": v1_content != v1_bytes,
                },
                failure_reason="the first shared revision has missing, extra, reordered, or wrongly separated lines",
            )
        )

        first_attachment_ok = (
            len(attachment_payloads) == 2
            and bool(v1_evidence.get("base_pass"))
            and v1_exact
        )
        checks.append(
            cls._check(
                "first_saved_attachment",
                first_attachment_ok,
                steps=list(range(30, 35)),
                dimension="final_object",
                expected="the first of exactly two post-baseline attachments is the exact v1 revision",
                observed=v1_evidence,
                failure_reason="the first Saved Messages attachment is missing, unsafe, unsent, stale, or has wrong bytes",
            )
        )

        final_exact = (
            len(attachment_payloads) == 2
            and expected_v2_bytes is not None
            and v2_content == expected_v2_bytes
            and note_content == expected_v2_bytes
        )
        checks.append(
            cls._check(
                "final_v2_exact_lines_and_newlines",
                final_exact,
                steps=[41, 42, 43, 45, 46, 47, 54, 55, 56, 58, 59, 60, 61, 62, 63, 64, 65, 66, 67, 68, 69, 70],
                dimension="content_parameter",
                expected={
                    "lines": expected_v2_lines,
                    "separator": "exactly one LF between adjacent lines and no trailing LF",
                    "newline_steps": list(NEWLINE_STEPS),
                },
                observed={
                    "attachment_lines": cls._logical_lines(v2_content),
                    "fsnotes_lines": cls._logical_lines(note_content),
                    "attachment_size": len(v2_bytes),
                    "fsnotes_size": len(note_bytes),
                    "attachment_app_title_prefix_stripped": v2_content != v2_bytes,
                    "fsnotes_app_title_prefix_stripped": note_content != note_bytes,
                },
                failure_reason="the final note has missing, extra, reordered, or wrongly separated lines",
            )
        )

        second_attachment_ok = (
            len(attachment_payloads) == 2
            and bool(v2_evidence.get("base_pass"))
            and expected_v2_bytes is not None
            and v2_content == expected_v2_bytes
        )
        checks.append(
            cls._check(
                "second_saved_attachment",
                second_attachment_ok,
                steps=list(range(71, 76)),
                dimension="final_object",
                expected="the second of exactly two post-baseline attachments is the exact final revision",
                observed=v2_evidence,
                failure_reason="the final Saved Messages attachment is missing, unsafe, unsent, stale, or has wrong bytes",
            )
        )

        prefix_ok = (
            bool(v1_content)
            and bool(v2_content)
            and v2_content.startswith(v1_content + b"\n")
            and len(v2_content) > len(v1_content)
            and hashlib.sha256(v1_content).digest() != hashlib.sha256(v2_content).digest()
        )
        checks.append(
            cls._check(
                "revision_prefix_and_distinct_hashes",
                prefix_ok,
                steps=[34, 41, 42, 43, 45, 46, 47, 54, 55, 56, 58, 59, 60, 61, 62, 63, 64, 65, 66, 67, 68, 69, 70, 75],
                dimension="source_process",
                expected="v1 bytes plus one LF are the exact prefix of a larger, hash-distinct v2",
                observed={
                    "v1_size": len(v1_content),
                    "v2_size": len(v2_content),
                    "v1_sha256": cls._sha256_bytes(v1_content),
                    "v2_sha256": cls._sha256_bytes(v2_content),
                    "v1_app_title_prefix_stripped": v1_content != v1_bytes,
                    "v2_app_title_prefix_stripped": v2_content != v2_bytes,
                },
                failure_reason="the two attachments do not prove the required ordered note revision chain",
            )
        )

        note_hash = cls._sha256_bytes(note_bytes)
        # The allowed note name is the only thing normalized here: the shared
        # blob must still be byte-identical to the actual FSNotes file, which
        # may carry the app-managed title (cf. the sibling 4_2 fix).
        fsnotes_equals_v2 = (
            note_path is not None
            and bool(v2_bytes)
            and note_bytes == v2_bytes
            and note_hash == v2_evidence.get("sha256")
        )
        checks.append(
            cls._check(
                "fsnotes_equals_final_attachment",
                fsnotes_equals_v2,
                steps=[70, 75],
                dimension="source_process",
                expected="the final attachment is byte-identical to the unique bound FSNotes file",
                observed={
                    "fsnotes_name": note_path.name if note_path is not None else None,
                    "fsnotes_sha256": note_hash,
                    "fsnotes_content_sha256": cls._sha256_bytes(note_content),
                    "attachment_name": v2_evidence.get("filename"),
                    "attachment_sha256": v2_evidence.get("sha256"),
                    "attachment_content_sha256": cls._sha256_bytes(v2_content),
                    "app_title_prefix_stripped": note_content != note_bytes,
                },
                failure_reason="the final attachment is not the exact current FSNotes object",
            )
        )

        ordered_ids = [int(row["id"]) for row in attachment_rows]
        ordered_timestamps = [int(row["timestamp"] or 0) for row in attachment_rows]
        timestamps_sorted = ordered_timestamps == sorted(ordered_timestamps)
        timestamps_distinct = len(set(ordered_timestamps)) == 2
        order_ok = (
            len(new_saved_rows) == 2
            and len(attachment_rows) == 2
            and ordered_ids == sorted(ordered_ids)
            and len(set(ordered_ids)) == 2
            and timestamps_sorted
        )
        checks.append(
            cls._check(
                "saved_outputs_business_order",
                order_ok,
                steps=[34, 75],
                dimension="source_process",
                expected="exactly v1 < v2 by distinct message id and non-decreasing current-session timestamp (equal timestamps are a non-blocking diagnostic)",
                observed={
                    "message_ids": ordered_ids,
                    "timestamps": ordered_timestamps,
                    "timestamps_distinct_diagnostic": timestamps_distinct,
                    "all_new_saved_ids": [int(row["id"]) for row in new_saved_rows],
                },
                failure_reason="Saved Messages outputs are missing, extra, duplicated, or out of order",
            )
        )

        observed = {
            "database_path": str(db_path),
            "fsnotes_documents": str(documents),
            "saved_messages_chat_id": self_chat_id,
            "minimum_message_id": minimum_message_id,
            "baseline_max_timestamp": baseline_max_timestamp,
            "new_saved_messages": [cls._message_summary(row) for row in new_saved_rows],
            "selected_source_messages": selected_sources,
            "note": {
                "path": str(note_path) if note_path is not None else None,
                "sha256": note_hash,
                "content_sha256": cls._sha256_bytes(note_content),
                "logical_lines": cls._logical_lines(note_content),
            },
            "attachment_revisions": [payload[0] for payload in attachment_payloads],
        }
        return checks, observed

    @classmethod
    def _result(
        cls,
        *,
        status: EvalStatus,
        message: str,
        udid: str,
        checks: list[dict[str, Any]],
        observed: Mapping[str, Any],
    ) -> EvalResult:
        failures = [check for check in checks if not check["pass"]]
        return EvalResult(
            status=status,
            message=message,
            metadata={
                "task_id": TASK_ID,
                "udid": udid,
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "checks": checks,
                "failures": failures,
                "observed": dict(observed),
                "step_coverage": cls._step_coverage(checks),
                "coverage_summary": {
                    "instruction_steps": 75,
                    "mapped_steps": 75,
                    "data_producing_steps": sorted(DATA_PRODUCING_STEPS),
                    "newline_steps": list(NEWLINE_STEPS),
                    "newline_check": "exact raw UTF-8 bytes with one LF between every requested adjacent line",
                    "final_ui": "not_required_after_terminal_share_submission",
                },
                "verifier_rules": [
                    "Human eval-only and automatic execution use this exact evaluator and RULESET_SHA256.",
                    "Only the bound Delta Chat database, FSNotes file, and Delta attachment blobs are authoritative.",
                    "Each copied source must equal one complete baseline message from the named chat and occupy its instructed line.",
                    "Every typed value and requested Return result is checked by exact raw-byte line equality.",
                    "The two attachments must be the only post-baseline Saved Messages outputs and must occur as v1 then v2.",
                    "The final attachment must be byte-identical to the bound final FSNotes file.",
                    "No trajectory, recording, screenshot, Appium session, initializer, or GUI action is used by this evaluator.",
                ],
            },
        )

    @classmethod
    def _step_coverage(cls, checks: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        by_name = {str(check["name"]): check for check in checks}
        coverage: list[dict[str, Any]] = []
        for group in STEP_GROUPS:
            names = list(group["checkpoint_names"])
            group_pass = all(name in by_name and bool(by_name[name].get("pass")) for name in names)
            for step in group["steps"]:
                coverage.append(
                    {
                        "step": step,
                        "role": (
                            "data_producing_or_compound"
                            if step in DATA_PRODUCING_STEPS
                            else "required_navigation"
                        ),
                        "checkpoint_names": names,
                        "mapping_basis": "shared read-only cross-object invariant",
                        "purpose": group["purpose"],
                        "dimensions": {
                            "final_object": "covered",
                            "content_parameter": "covered",
                            "source_process": "covered_by_source_revision_and_order_invariants",
                            "final_ui": "not_applicable_after_terminal_share",
                        },
                        "pass": group_pass,
                    }
                )
        return sorted(coverage, key=lambda item: int(item["step"]))

    @staticmethod
    def _check(
        name: str,
        passed: bool,
        *,
        steps: list[int],
        dimension: str,
        expected: Any,
        observed: Any,
        failure_reason: str,
    ) -> dict[str, Any]:
        return {
            "name": name,
            "pass": bool(passed),
            "steps": steps,
            "dimension": dimension,
            "expected": expected,
            "observed": observed,
            "failure_reason": None if passed else failure_reason,
        }

    @classmethod
    def _attachment_blob(
        cls,
        *,
        db_path: Path,
        row: sqlite3.Row,
        sent_state: int,
        baseline_max_timestamp: int,
    ) -> tuple[dict[str, Any], bytes]:
        params = cls._parse_params(row["param"])
        filename = params.get("v", "")
        raw_blob = params.get("f", "")
        blob_root = (db_path.parent / "dc.db-blobs").resolve()
        blob_path: Path | None = None
        safe = False
        if raw_blob.startswith("$BLOBDIR/"):
            candidate = (blob_root / raw_blob.removeprefix("$BLOBDIR/")).resolve()
            if candidate.is_relative_to(blob_root):
                blob_path = candidate
                safe = True
        blob_bytes = blob_path.read_bytes() if safe and blob_path and blob_path.is_file() else b""
        try:
            blob_bytes.decode("utf-8-sig")
            utf8_ok = bool(blob_bytes)
        except UnicodeDecodeError:
            utf8_ok = False
        base_pass = (
            filename in NOTE_NAMES
            and int(row["state"]) == sent_state
            and int(row["timestamp"] or 0) > baseline_max_timestamp
            and safe
            and bool(blob_bytes)
            and utf8_ok
        )
        return (
            {
                "base_pass": base_pass,
                "message_id": int(row["id"]),
                "filename": filename,
                "state": int(row["state"]),
                "timestamp": int(row["timestamp"] or 0),
                "blob_path": str(blob_path) if blob_path else None,
                "blob_path_safe": safe,
                "size": len(blob_bytes),
                "sha256": cls._sha256_bytes(blob_bytes),
                "logical_lines": cls._logical_lines(cls._strip_app_title(blob_bytes)),
            },
            blob_bytes,
        )

    @staticmethod
    def _resolve_line_spec(
        spec: Sequence[tuple[str, str]],
        sources: Mapping[str, Mapping[str, Any]],
    ) -> list[str] | None:
        lines: list[str] = []
        for kind, value in spec:
            if kind == "literal":
                lines.append(value)
            elif value in sources:
                lines.append(str(sources[value]["text"]))
            else:
                return None
        return lines

    @staticmethod
    def _expected_bytes(lines: Sequence[str] | None) -> bytes | None:
        if lines is None:
            return None
        return "\n".join(lines).encode("utf-8")

    @staticmethod
    def _strip_app_title(payload: bytes) -> bytes:
        """Strip only the explicit FSNotes app-managed creation-title prefix.

        Mirrors the sibling 4_2/4_3 normalizers: the creation title is either
        merged with the first heading or on its own line, and only those two
        exact shapes are removed. Every other byte is compared strictly, so a
        different prefix, an extra line, CRLF, or a trailing LF still FAILs.
        """

        title = NOTE_TITLE.encode("utf-8")
        heading = NOTE_HEADING.encode("utf-8")
        if payload.startswith(title + heading):
            return payload[len(title):]
        if payload.startswith(title + b"\n" + heading):
            return payload[len(title) + 1:]
        return payload

    @staticmethod
    def _logical_lines(payload: bytes) -> list[str]:
        if not payload:
            return []
        try:
            text = payload.decode("utf-8-sig")
        except UnicodeDecodeError:
            return []
        normalized = text.replace("\r\n", "\n").replace("\r", "\n")
        return normalized.split("\n")

    @staticmethod
    def _message_summary(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "id": int(row["id"]),
            "chat_id": int(row["chat_id"]),
            "chat_name": str(row["chat_name"]),
            "from_id": int(row["from_id"]),
            "to_id": int(row["to_id"]),
            "type": int(row["type"]),
            "state": int(row["state"]),
            "timestamp": int(row["timestamp"] or 0),
            "timestamp_sent": int(row["timestamp_sent"] or 0),
            "text": str(row["txt"]),
            "attachment_name": DeltaChatRouteHandoffStateEvaluator._param_value(row["param"], "v"),
        }

    @staticmethod
    def _resolve_fsnotes_documents(*, udid: str, bundle_id: str) -> Path:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "data"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode == 0 and proc.stdout.strip():
            from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
            root = remap_simulator_container_path(proc.stdout.strip(), udid)
        else:
            container = _find_app_data_container_by_metadata(udid=udid, bundle_id=bundle_id)
            if container is None:
                raise RuntimeError(f"FSNotes data-container lookup failed: {proc.stderr.strip()}")
            root = container.resolve()
        documents = (root / "Documents").resolve()
        if not documents.is_dir():
            raise FileNotFoundError(f"FSNotes Documents directory is missing: {documents}")
        return documents

    @staticmethod
    @contextmanager
    def _sqlite_snapshot(db_path: Path) -> Iterator[Path]:
        """Create a consistent host-side copy through a read-only SQLite connection."""

        with tempfile.TemporaryDirectory(prefix="ios-deltachat-handoff-eval-") as temp_dir:
            snapshot = Path(temp_dir) / "dc.db"
            source = sqlite3.connect(f"file:{db_path.as_posix()}?mode=ro", uri=True)
            destination = sqlite3.connect(snapshot)
            try:
                source.backup(destination)
            finally:
                destination.close()
                source.close()
            yield snapshot

    @staticmethod
    def _parse_params(raw: Any) -> dict[str, str]:
        values: dict[str, str] = {}
        for line in str(raw or "").splitlines():
            if "=" in line:
                key, value = line.split("=", 1)
                values[key] = value
        return values

    @classmethod
    def _param_value(cls, raw: Any, key: str) -> str:
        return cls._parse_params(raw).get(key, "")

    @staticmethod
    def _sha256_bytes(payload: bytes) -> str | None:
        return hashlib.sha256(payload).hexdigest() if payload else None
